corrected_code:
package trials

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/clinical"
)

type StatusUpdatePayload struct {
	EligibilityStatus string `json:"eligibility_status"`
}

type TrialController struct {
	TrialService clinical.TrialService
}

func (tc *TrialController) UpdateParticipantEligibility(c echo.Context) error {
	participantID := c.Param("participantID")
	userToken := c.Get("user").(*jwt.Token)
	claims := userToken.Claims.(jwt.MapClaims)
	researcherSiteID := claims["site_id"].(string)

	var body StatusUpdatePayload
	if err := c.Bind(&body); err != nil {
		return c.JSON(http.StatusBadRequest, echo.Map{"error": "Invalid request"})
	}

	err := tc.TrialService.UpdateStatusForSite(c.Request().Context(), participantID, researcherSiteID, body.EligibilityStatus)
	if err != nil {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Participant not found or access denied for this site"})
	}

	return c.JSON(http.StatusOK, echo.Map{"updated": true})
}
